python3 - <<'PYEOF'
p = '/Users/guillaumeloulier/PhpstormProjects/oss/elephc/.claude/worktrees/streams-csv-signature/src/ir_lower/expr/call_arg_coercion.rs'
s = open(p).read()
s = s.replace(
    """/// This is php's out-parameter idiom — `$x = null; f($x);` with `function f(&$a) { $a = 5; }` —
/// and the whole point of it is that `$x` is `int(5)` afterwards. The checker widened the
/// parameter to `<written>|null` when it saw the body write, and re-typed its own view of the
/// caller's variable; the LOWERING keeps its own local-type map, so without this the load after
/// the call still carried `php=null` and every read of it constant-folded to NULL. The write
/// itself always happened — the callee stores through the pointer — which is why nothing warned.
///
/// No conversion is emitted: the caller's slot is handed over as it is, and codegen's
/// `plan_ref_arg_writebacks` boxes it into a temporary Mixed cell for the call and unboxes it
/// back afterwards. Only the TYPE has to move.""",
    """/// This is php's out-parameter idiom — `$x = null; f($x);` with `function f(&$a) { $a = 5; }` —
/// and the whole point of it is that `$x` is `int(5)` afterwards. The checker widened the
/// parameter to `mixed` when it saw the body write, and re-typed its own view of the caller's
/// variable; the LOWERING keeps its own local-type map, so without this the load after the call
/// still carried `php=null` and every read of it constant-folded to NULL. The write itself
/// always happened — the callee stores through the pointer — which is why nothing warned.""",
)
open(p, 'w').write(s)

p = '/Users/guillaumeloulier/PhpstormProjects/oss/elephc/.claude/worktrees/streams-csv-signature/src/types/checker/inference/expr/effects.rs'
s = open(p).read()
s = s.replace(
    """            // A variable that held NULL and reached a by-reference parameter the callee WRITES
            // comes back holding whatever was written. The signature already says so — the
            // parameter was widened to `<written>|null` when the body was checked — so adopting
            // it here is what finally makes the write visible: leaving the caller typed `null`""",
    """            // A variable that held NULL and reached a by-reference parameter the callee WRITES
            // comes back holding whatever was written. The signature already says so — the
            // parameter was widened to `mixed` when the body was checked — so adopting it here
            // is what finally makes the write visible: leaving the caller typed `null`""",
)
open(p, 'w').write(s)
print("comments corrected")
